// Loads the pure-logic objects out of the ORIGINAL PromptForge.html into a vm sandbox so goldens can be
// generated by the real JavaScript instead of being written by hand.
const fs = require('fs');
const vm = require('vm');

function load(htmlPath) {
  const lines = fs.readFileSync(htmlPath, 'utf8').split('\n');
  const blocks = [];
  function grab(name, kind = 'const') {
    const start = lines.findIndex(l => l.startsWith(`${kind} ${name} =`) || l.startsWith(`${kind} ${name} {`));
    if (start < 0) throw new Error('not found: ' + name);
    if (/;\s*$/.test(lines[start]) && !/[{\[(]\s*$/.test(lines[start])) { blocks.push(lines[start]); return; }
    let end = start;
    while (!(lines[end] === '};' || lines[end] === '})();' || lines[end] === '}')) end++;
    blocks.push(lines.slice(start, end + 1).join('\n'));
  }
  for (const n of ['Utils', 'CONFIG', 'STOPWORDS', 'ScoringProfiles', 'TemplateEngine', 'Analyzer', 'SecurityScanner', 'PromptCleaner',
    'PromptTools', 'Validator', 'FormatConverter', 'ReadabilityEngine', 'RiskLinter', 'DuplicateFinder', 'MessageComposer', 'RealTokenizer', 'TokenEstimator']) grab(n);
  // The original validates/parses XML with the browser's DOMParser. Node has none, so use xmldom (a spec-following
  // parser) behind the same surface the app touches. Malformed XML makes xmldom throw, which the original's own
  // try/catch turns into { valid: false }, exactly as a browser's parsererror does. Install with:
  //   npm install --no-save @xmldom/xmldom
  let DOMParserShim;
  try {
    const { DOMParser: X } = require('@xmldom/xmldom');
    DOMParserShim = class {
      parseFromString(s, mime) { const d = new X({ onError: () => {} }).parseFromString(s, mime); d.querySelector = () => null; return d; }
    };
  } catch (_) { /* xmldom not installed: XML goldens will be wrong; gen_goldens.js refuses to run without it */ }
  // RealTokenizer reads its gzip+base64 vocab from a <script id="cl100kVocabData"> element and gunzips it with
  // the browser's DecompressionStream. Node 18+ has the same stream classes, so only `document` needs a shim.
  const html = fs.readFileSync(htmlPath, 'utf8');
  const vm64 = (html.match(/id="cl100kVocabData">([A-Za-z0-9+\/=\s]+)<\/script>/) || [])[1] || '';
  const document = { getElementById: id => (id === 'cl100kVocabData' ? { textContent: vm64 } : null) };
  const ctx = { console, Date, Math, JSON, Set, Map, RegExp, Intl, document, DOMParser: DOMParserShim,
    window: { DecompressionStream }, DecompressionStream, atob, Blob, Response, TextEncoder, Uint8Array, Promise, setTimeout };
  vm.createContext(ctx);
  const src = blocks.join('\n') + '\nthis.__o = { Utils, CONFIG, TemplateEngine, Analyzer, SecurityScanner, PromptCleaner, PromptTools, Validator, FormatConverter, ReadabilityEngine, RiskLinter, DuplicateFinder, MessageComposer, RealTokenizer, TokenEstimator, STOPWORDS };';
  vm.runInContext(src, ctx, { filename: 'PromptForge.html(extracted)' });
  return ctx.__o;
}
module.exports = { load, hasDomParser: () => { try { require('@xmldom/xmldom'); return true; } catch (_) { return false; } } };
if (require.main === module) {
  const o = load(process.argv[2]);
  for (const [k, v] of Object.entries(o)) console.log(k, v && typeof v === 'object' && !(v instanceof Set) ? Object.keys(v).join(',') : typeof v);
}
